<script setup lang="ts">import { ref } from 'vue'; type Dock='ai'|'chat'|'contact'; const active=ref<Dock|null>(null); const items:{id:Dock;icon:string;label:string}[]=[{id:'ai',icon:'🤖',label:'AI 助理'},{id:'chat',icon:'💬',label:'立即互動'},{id:'contact',icon:'📞',label:'真人諮詢'}]; const toggle=(id:Dock)=>{active.value=active.value===id?null:id}</script>
<template><aside class="fixed-right-widget-panel" aria-label="浮動服務導覽"><div class="widget-icon-bar"><button v-for="item in items" :key="item.id" class="widget-tab-btn" :class="{active:active===item.id}" @click="toggle(item.id)"><span class="tab-icon">{{ item.icon }}</span><span class="tab-label">{{ item.label }}</span></button></div><div v-if="active" class="widget-drawer-content"><div class="drawer-header-bar"><h4>服務導覽</h4><button class="btn-close-drawer" aria-label="關閉服務導覽" @click="active=null">✕</button></div><div class="drawer-body-container"><p class="drawer-tip">{{ active==='contact'?'專屬顧問直線：(02) 2345-6789':'此服務入口將於後續單元完成。' }}</p><RouterLink v-if="active==='contact'" class="btn-submit-contact" to="/contact">請與我聯絡 ❯</RouterLink></div></div></aside></template>
